## Why This Is Asked
This question tests the ability to combine shortest-path computation, path counting, and path reconstruction into a cohesive solution. It also evaluates handling of multiple equal-cost routes and lexicographic tie-breaking.

## Key Concepts
- Dijkstra's algorithm for O(m log n) shortest paths
- Shortest-path DAG construction
- Topological ordering by distance values
- DP for counting distinct shortest paths
- Lexicographic path reconstruction

## Code Example
```javascript
function shortestStats(n, edges, s, t) {
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) {
    adj[u].push([v, w]);
  }

  const dist = new Array(n).fill(Infinity);
  const pq = [[0, s]];
  dist[s] = 0;

  while (pq.length) {
    const [d, u] = pq.pop();
    if (d > dist[u]) continue;
    for (const [v, w] of adj[u]) {
      if (dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
        pq.push([dist[v], v]);
      }
    }
  }

  const dag = Array.from({ length: n }, () => []);
  for (let u = 0; u < n; u++) {
    for (const [v, w] of adj[u]) {
      if (dist[u] + w === dist[v]) {
        dag[u].push(v);
      }
    }
  }

  const ways = new Array(n).fill(0);
  ways[s] = 1;
  const order = Array.from({ length: n }, (_, i) => i)
    .sort((a, b) => dist[a] - dist[b]);

  for (const u of order) {
    for (const v of dag[u]) {
      ways[v] = (ways[v] + ways[u]) % 1000000007;
    }
  }

  const path = [];
  let curr = t;
  while (curr !== null) {
    path.unshift(curr);
    const preds = dag
      .map((list, u) => list.includes(curr) ? u : -1)
      .filter(u => u >= 0 && dist[curr] === dist[u] + 
        adj[u].find(([v]) => v === curr)?.[1]);
    preds.sort((a, b) => a - b);
    curr = preds.length > 0 ? preds[0] : null;
    if (curr === s) {
      path.unshift(s);
      break;
    }
  }

  return { distance: dist[t], ways: ways[t], path };
}
```

## Complexity Analysis
- Dijkstra: O(m log n)
- DAG construction: O(m)
- DP counting: O(m)
- Path reconstruction: O(n + m)
- Overall: O(m log n)

## Why This Is Asked
Tests mastery of graph algorithms, state expansion techniques, and path reconstruction under constraints.

## Key Concepts
- Dijkstra's algorithm on expanded state space (node, used)
- Edge relaxation with and without discount application
- Path reconstruction across state transitions

## Code Example
```javascript
function shortestWithDiscounts(n, edges, s, t, K) {
  const adj = Array.from({length: n}, ()=>[]);
  for(const [u,v,w] of edges){ adj[u].push([v,w]); }
  const INF = Number.POSITIVE_INFINITY;
  const dist = Array.from({length: n}, ()=> Array(K+1).fill(INF));
  const prev = Array.from({length: n}, ()=> Array(K+1).fill(null));

  const pq = new MinHeap();
  dist[s][0] = 0;
  pq.insert([s,0,0]); // [node, used, distance]

  while(!pq.isEmpty()){
    const [u,used,d] = pq.extractMin();
    if(d > dist[u][used]) continue;
    if(u === t) break;

    for(const [v,w] of adj[u]){
      // Without discount
      if(d + w < dist[v][used]){
        dist[v][used] = d + w;
        prev[v][used] = [u,used];
        pq.insert([v,used,d+w]);
      }
      // With discount if available
      if(used < K && d < dist[v][used+1]){
        dist[v][used+1] = d;
        prev[v][used+1] = [u,used];
        pq.insert([v,used+1,d]);
      }
    }
  }

  // Find optimal state at target
  let minDist = INF, minUsed = -1;
  for(let k=0;k<=K;k++){
    if(dist[t][k] < minDist){
      minDist = dist[t][k];
      minUsed = k;
    }
  }

  // Path reconstruction
  const path = [];
  let curr = [t,minUsed];
  while(curr && prev[curr[0]][curr[1]]){
    path.unshift(curr[0]);
    curr = prev[curr[0]][curr[1]];
  }
  if(curr[0] === s) path.unshift(s);

  return {distance: minDist, path};
}
```

## Edge Cases
- Unreachable target: return INF distance
- K=0: reduces to standard Dijkstra
- K larger than path length: effectively unlimited discounts
- Multiple optimal states: choose minimal used count

## Why This Is Asked
Explores a practical, augmented Trie approach blending prefix queries with order-statistics, a gap in typical BST/trie questions.

## Key Concepts
- Trie augmentation with endCount and subCount
- Duplicates handled via endCount
- Lexicographic kthWord via endCount before children

## Code Example
```javascript
class Node {
  constructor() {
    this.next = new Map();
    this.end = 0;
    this.sub = 0;
  }
}
class Trie {
  constructor(){ this.root = new Node(); }
  insert(w){ let cur=this.root; cur.sub++; for(const ch of w){ if(!cur.next.has(ch)) cur.next.set(ch,new Node()); cur=cur.next.get(ch); cur.sub++; } cur.end++; }
  delete(w){ let cur=this.root; cur.sub--; for(const ch of w){ cur=cur.next.get(ch); cur.sub--; } cur.end--; }
  countPrefix(p){ let cur=this.root; for(const ch of p){ if(!cur.next.has(ch)) return 0; cur=cur.next.get(ch); } return cur.sub; }
  kthWord(k){ let res=''; let node=this.root; while(true){ if(k <= node.end) return res; k -= node.end; // skip words ending here
      // iterate in lexical order
      const keys = Array.from(node.next.keys()).sort();
      for(const ch of keys){ const child=node.next.get(ch); if(child.sub >= k){ res += ch; node = child; break; } else k -= child.sub; }
    }
  }
}
```

